const rtdal003414Source0001 = `lsm_l_ent <- function(landscape,
                           neighbourhood = 4,
                           base = "log2") {
    landscape <- landscape_as_list(landscape)

    result <- lapply(X = landscape,
                     FUN = lsm_l_ent_calc,
                     neighbourhood = neighbourhood,
                     base = base)

    layer <- rep(seq_along(result),
                 vapply(result, nrow, FUN.VALUE = integer(1)))

    result <- do.call(rbind, result)

    tibble::add_column(result, layer, .before = TRUE)
}`

const rtdal003414Source0002 = `lsm_l_ent_calc <- function(landscape, neighbourhood, base, extras = NULL){

    # convert to matrix
    if (!inherits(x = landscape, what = "matrix")) {
        landscape <- terra::as.matrix(landscape, wide = TRUE)
    }

    # all values NA
    if (all(is.na(landscape))) {
        return(tibble::new_tibble(list(level = "landscape",
                              class = as.integer(NA),
                              id = as.integer(NA),
                              metric = "ent",
                              value = as.double(NA))))
    }

    if (!is.null(extras)){
        comp <- extras$comp
    } else {
        com <- rcpp_get_coocurrence_matrix(landscape, directions = as.matrix(neighbourhood))
        comp <- rcpp_get_entropy(colSums(com), base)
    }

    return(tibble::new_tibble(list(level = rep("landscape", length(comp)),
                 class = rep(as.integer(NA), length(comp)),
                 id = rep(as.integer(NA), length(comp)),
                 metric = rep("ent", length(comp)),
                 value = as.double(comp))))
}`

