const rtdal003498Source0004 = `test_that("lsm_c_ai handles NAs correctly", {
    r <- terra::rast(nrow = 10, ncol = 10)
    r[] <- 1
    expect_equal(lsm_c_ai(r)$value, 100)
    r[1, 1] <- NA
    expect_equal(lsm_c_ai(r)$value, 100)
    r[2, 5] <- NA
    expect_equal(lsm_c_ai(r)$value, 98.86364, tolerance = 0.00001)
})`

